 [F("parents", "Parents-to-be", "text", "Priya & Sam"), TXT("due", "Due date", "late May"), CH("type", "Celebration", ["Baby shower", "Sprinkle (2nd+ baby)", "Sip & see (after birth)", "Co-ed shower", "Virtual shower"]), CH("vibe", "Vibe", ["Brunch", "Garden tea", "Evening mocktails", "Casual at home"])],
